import { useEffect, useMemo, useState } from 'react';
import { ArrowLeft, ArrowRight, BarChart3, Bell, CalendarDays, Check, ChevronLeft, ChevronRight, Clock3, Database, LayoutGrid, Leaf, Menu, Moon, Pause, Play, Plus, RotateCcw, Settings2, ShieldCheck, Sparkles, SunMedium, Trash2, UserRound, X } from 'lucide-react';
import { isSupabaseConfigured, supabase } from './lib/supabase';
import { fetchPlannerData, getCurrentUser, removeTask, signInWithEmail, signOut, signUpWithEmail, upsertDailyEntry, upsertTask } from './services/taskService';

const STORAGE_KEY = 'daymark-focus-state';
const initialTasks = [
  { id: 1, title: 'Finish the project proposal', detail: 'Review the final numbers and send the draft', time: '09:30', priority: 'High', done: false },
  { id: 2, title: 'Reply to the design team', detail: 'Close the three open decisions', time: '11:00', priority: 'Medium', done: false },
  { id: 3, title: 'Plan tomorrow before signing off', detail: 'Choose one clear first move', time: '16:30', priority: 'Low', done: false },
];
const today = startOfDay(new Date());

function startOfDay(date) { return new Date(date.getFullYear(), date.getMonth(), date.getDate()); }
function keyFor(date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; }
function formatDate(date, options) { return date.toLocaleDateString('en-US', options); }
function loadState() { try { const saved = JSON.parse(localStorage.getItem(STORAGE_KEY)); if (!saved) return { tasks: initialTasks, habits: initialTasks.map((task) => ({ ...task, startTime: task.time, endTime: '' })), habitLogs: {}, notes: {}, reminders: {} }; return { ...saved, habits: saved.habits || saved.tasks.map((task) => ({ ...task, startTime: task.time, endTime: '' })), habitLogs: saved.habitLogs || {} }; } catch { return { tasks: initialTasks, habits: initialTasks.map((task) => ({ ...task, startTime: task.time, endTime: '' })), habitLogs: {}, notes: {}, reminders: {} }; } }

export default function App() {
  const [state, setState] = useState(loadState);
  const [selectedDate, setSelectedDate] = useState(today);
  const [calendarDate, setCalendarDate] = useState(today);
  const [view, setView] = useState('Today');
  const [menuOpen, setMenuOpen] = useState(false);
  const [modal, setModal] = useState(null);
  const [toast, setToast] = useState('');
  const [focusSeconds, setFocusSeconds] = useState(25 * 60);
  const [focusRunning, setFocusRunning] = useState(false);
  const [user, setUser] = useState(null);
  const [authOpen, setAuthOpen] = useState(false);
  const [showAuthPage, setShowAuthPage] = useState(true);
  const [authError, setAuthError] = useState('');
  const currentKey = keyFor(selectedDate);
  const habits = state.habits || [];
  const habitLogs = state.habitLogs || {};
  const tasks = habits.map((habit) => ({ ...habit, done: habitLogs[currentKey]?.includes(habit.id), time: habit.endTime ? `${habit.startTime} - ${habit.endTime}` : habit.startTime }));
  const pending = tasks.filter((task) => !task.done);
  const completed = habits.filter((habit) => habitLogs[currentKey]?.includes(habit.id)).length;
  const isToday = currentKey === keyFor(today);
  const preferences = state.preferences || {};

  useEffect(() => localStorage.setItem(STORAGE_KEY, JSON.stringify(state)), [state]);
  useEffect(() => {
    let active = true;
    async function loadRemotePlanner() {
      if (!isSupabaseConfigured) return;
      try {
        const currentUser = await getCurrentUser();
        if (!active || !currentUser) return;
        setUser(currentUser);
        setShowAuthPage(false);
        const remoteState = await fetchPlannerData(currentUser.id);
        if (remoteState?.tasks?.length) setState(remoteState);
      } catch (error) {
        if (active) setToast(error.message || 'Could not load cloud data');
      }
    }
    loadRemotePlanner();
    const subscription = supabase?.auth.onAuthStateChange((_event, session) => setUser(session?.user || null));
    return () => { active = false; subscription?.data?.subscription?.unsubscribe(); };
  }, []);
  useEffect(() => { if (!toast) return undefined; const timer = setTimeout(() => setToast(''), 2200); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { if (!focusRunning) return undefined; const timer = setInterval(() => setFocusSeconds((seconds) => seconds > 0 ? seconds - 1 : 25 * 60), 1000); return () => clearInterval(timer); }, [focusRunning]);
  useEffect(() => { if (!focusRunning && preferences.focusLength) setFocusSeconds(Number(preferences.focusLength) * 60); }, [preferences.focusLength, focusRunning]);

  const changeDate = (offset) => { const next = new Date(selectedDate); next.setDate(next.getDate() + offset); setSelectedDate(startOfDay(next)); setCalendarDate(startOfDay(next)); };
  const selectDate = (date) => { setSelectedDate(date); setCalendarDate(date); };
  const sync = (operation) => { if (user) operation().catch((error) => setToast(error.message || 'Cloud sync failed')); };
  const toggleHabit = (id) => { setState((current) => { const logged = current.habitLogs?.[currentKey] || []; const nextLogged = logged.includes(id) ? logged.filter((habitId) => habitId !== id) : [...logged, id]; return { ...current, habitLogs: { ...(current.habitLogs || {}), [currentKey]: nextLogged } }; }); };
  const toggleTask = (id) => toggleHabit(id);
  const deleteTask = (id) => { setState((current) => ({ ...current, habits: current.habits.filter((habit) => habit.id !== id) })); setToast('Habit removed'); };
  const saveTask = (task) => { const nextHabit = { ...task, startTime: task.time || 'Anytime', endTime: task.endTime || '' }; setState((current) => ({ ...current, habits: current.habits.some((item) => item.id === nextHabit.id) ? current.habits.map((item) => item.id === nextHabit.id ? nextHabit : item) : [...current.habits, nextHabit] })); setModal(null); setToast(task.id ? 'Habit updated' : 'Habit added'); };
  const saveHabit = (habit) => { setState((current) => ({ ...current, habits: current.habits.some((item) => item.id === habit.id) ? current.habits.map((item) => item.id === habit.id ? habit : item) : [...current.habits, habit] })); setModal(null); setToast(habit.id ? 'Habit updated' : 'Habit added'); };
  const saveNote = (value) => { setState((current) => ({ ...current, notes: { ...current.notes, [currentKey]: value } })); sync(() => upsertDailyEntry('daily_notes', currentKey, value, user.id)); setToast('Note saved'); };
  const saveReminder = (value) => { setState((current) => ({ ...current, reminders: { ...current.reminders, [currentKey]: value } })); sync(() => upsertDailyEntry('daily_reminders', currentKey, value, user.id)); setToast(value ? 'Reminder set' : 'Reminder cleared'); };
  const handleAuth = async (email, password, mode) => { setAuthError(''); try { const authenticatedUser = mode === 'signup' ? await signUpWithEmail(email, password) : await signInWithEmail(email, password); if (!authenticatedUser) { setAuthError('Account created. Check your email to confirm your address, then sign in.'); return; } setUser(authenticatedUser); setShowAuthPage(false); setAuthOpen(false); setToast(mode === 'signup' ? 'Account created' : 'Signed in'); } catch (error) { setAuthError(error.message || 'Authentication failed. Check your email and password.'); } };
  const handleSignOut = async () => { await signOut(); setUser(null); setShowAuthPage(true); setToast('Signed out'); };
  const minutes = String(Math.floor(focusSeconds / 60)).padStart(2, '0'); const seconds = String(focusSeconds % 60).padStart(2, '0');

  if (showAuthPage) return <AuthLanding configured={isSupabaseConfigured} onSubmit={handleAuth} error={authError} onContinue={() => { setAuthError(''); setShowAuthPage(false); }} />;

  return <div className={`app-shell ${preferences.compact ? 'compact-tasks' : ''} ${preferences.reduceMotion ? 'reduce-motion' : ''}`}>
    <aside className={`sidebar ${menuOpen ? 'is-open' : ''}`}><div className="brand"><span className="brand-mark"><Leaf size={17} /></span>daymark</div><nav className="side-nav"><button className={view === 'Today' ? 'active' : ''} onClick={() => { setView('Today'); setMenuOpen(false); }}><SunMedium size={17} />Today</button><button className={view === 'Insights' ? 'active' : ''} onClick={() => { setView('Insights'); setMenuOpen(false); }}><LayoutGrid size={17} />Insights</button><button className={view === 'Settings' ? 'active' : ''} onClick={() => { setView('Settings'); setMenuOpen(false); }}><Settings2 size={17} />Settings</button></nav><div className="side-quote"><Sparkles size={17} /><strong>Do less, better.</strong><span>Protect your attention for the work that matters.</span></div><div className="account-box">{user ? <><span className="account-label">SYNCED ACCOUNT</span><strong>{user.email}</strong><button onClick={handleSignOut}>Sign out</button></> : <><span className="account-label">{isSupabaseConfigured ? 'CLOUD SYNC' : 'LOCAL MODE'}</span><strong>{isSupabaseConfigured ? 'Keep your tasks everywhere.' : 'Your browser saves locally.'}</strong><button onClick={() => setAuthOpen(true)}>{isSupabaseConfigured ? 'Sign in' : 'Connect account'}</button></>}</div></aside>
    {menuOpen && <button className="mobile-scrim" onClick={() => setMenuOpen(false)} aria-label="Close navigation" />}
    <main><header className="topbar"><button className="mobile-menu-button" onClick={() => setMenuOpen(true)} aria-label="Open navigation"><Menu size={20} /></button><div><div className="kicker">{formatDate(selectedDate, { weekday: 'long', month: 'long', day: 'numeric' })}</div><h1>{view === 'Today' ? `Make room for focus${preferences.name ? `, ${preferences.name}.` : '.'}` : view}</h1></div><div className="date-control"><button onClick={() => changeDate(-1)} aria-label="Previous day"><ArrowLeft size={16} /></button><div className="today-label">{isToday ? 'Today' : formatDate(selectedDate, { month: 'short', day: 'numeric' })}</div><button onClick={() => changeDate(1)} aria-label="Next day"><ArrowRight size={16} /></button><button className="icon-btn" onClick={() => selectDate(today)} aria-label="Jump to today"><SunMedium size={16} /></button></div></header>
      {view === 'Today' ? <div className="content-grid"><section><div className="focus-hero panel"><div><div className="eyebrow">Next up</div><h2>{pending[0]?.title || 'Your list is clear.'}</h2><p>{pending[0]?.detail || 'A rare and useful feeling. Take the win.'}</p><div className="focus-meta"><span><Clock3 size={14} />{pending[0]?.time || 'No deadline'}</span><span className={`priority ${pending[0]?.priority?.toLowerCase() || 'low'}`}>{pending[0]?.priority || 'Open'}</span></div></div><div className="focus-timer"><span className="timer-label">Focus session</span><strong>{minutes}:{seconds}</strong><button onClick={() => setFocusRunning((running) => !running)}>{focusRunning ? <Pause size={15} /> : <Play size={15} />}{focusRunning ? 'Pause' : 'Start'}</button></div></div><div className="section-head"><div><div className="eyebrow">{completed} complete · {pending.length} remaining</div><h2>Today’s tasks</h2></div><button className="text-btn" onClick={() => setModal({ type: 'task', task: null })}><Plus size={14} />New task</button></div><div className="task-list">{tasks.map((task) => <TaskRow key={task.id} task={task} onToggle={() => toggleTask(task.id)} onEdit={() => setModal({ type: 'task', task })} onDelete={() => deleteTask(task.id)} />)}</div>{!tasks.length && <p className="empty-copy">No tasks planned for this day. Keep it intentionally light.</p>}<button className="add-task" onClick={() => setModal({ type: 'task', task: null })}><Plus size={16} />Add another task</button></section><aside className="right-column"><CalendarPanel calendarDate={calendarDate} selectedDate={selectedDate} state={state} onSelect={selectDate} onMonthChange={(offset) => { const next = new Date(calendarDate); next.setMonth(next.getMonth() + offset); setCalendarDate(next); }} /><NotesPanel value={state.notes[currentKey] || ''} date={selectedDate} onSave={saveNote} /><ReminderPanel value={state.reminders[currentKey] || ''} onSave={saveReminder} /></aside></div> : view === 'Insights' ? <InsightsView state={state} /> : <SettingsView state={state} setState={setState} user={user} onSignOut={handleSignOut} />}</main>
    {modal?.type === 'task' && <TaskModal task={modal.task} onClose={() => setModal(null)} onSave={saveTask} />}{authOpen && <AuthModal onClose={() => setAuthOpen(false)} onSubmit={handleAuth} configured={isSupabaseConfigured} />}{toast && <div className="toast" role="status">{toast}</div>}
  </div>;
}

function TaskRow({ task, onToggle, onEdit, onDelete }) { return <div className={`task-row ${task.done ? 'done' : ''}`}><button className="check" onClick={onToggle} aria-label={`Complete ${task.title}`}>{task.done && <Check size={16} />}</button><div className="task-copy"><p className="task-title">{task.title}</p><span>{task.detail}</span></div><div className="task-info"><span className={`priority ${task.priority.toLowerCase()}`}>{task.priority}</span><span className="task-time">{task.time}</span></div><div className="task-actions"><button onClick={onEdit} aria-label={`Edit ${task.title}`}>Edit</button><button onClick={onDelete} aria-label={`Delete ${task.title}`}><Trash2 size={14} /></button></div></div>; }

function CalendarPanel({ calendarDate, selectedDate, state, onSelect, onMonthChange }) { const days = useMemo(() => { const y = calendarDate.getFullYear(); const m = calendarDate.getMonth(); const first = new Date(y, m, 1).getDay(); const total = new Date(y, m + 1, 0).getDate(); const cells = []; for (let i = 0; i < first; i += 1) cells.push({ muted: true, day: '' }); for (let day = 1; day <= total; day += 1) cells.push({ date: new Date(y, m, day), day }); while (cells.length < 35) cells.push({ muted: true, day: '' }); return cells; }, [calendarDate]); return <section className="panel calendar-panel"><div className="calendar-head"><strong>{formatDate(calendarDate, { month: 'long', year: 'numeric' })}</strong><div><button className="mini-btn" onClick={() => onMonthChange(-1)} aria-label="Previous month"><ChevronLeft size={16} /></button><button className="mini-btn" onClick={() => onMonthChange(1)} aria-label="Next month"><ChevronRight size={16} /></button></div></div><div className="week">{['SU', 'MO', 'TU', 'WE', 'TH', 'FR', 'SA'].map((day) => <span key={day}>{day}</span>)}</div><div className="days">{days.map((cell, index) => { const dayKey = cell.date && keyFor(cell.date); const marked = dayKey && (state.notes[dayKey] || state.reminders[dayKey] || state.tasks.some((task) => task.day === dayKey)); return <button key={index} disabled={cell.muted} className={`day ${cell.muted ? 'muted' : ''} ${dayKey === keyFor(selectedDate) ? 'selected' : ''} ${marked ? 'has-note' : ''}`} onClick={() => cell.date && onSelect(cell.date)}>{cell.day}</button>; })}</div></section>; }
function NotesPanel({ value, date, onSave }) { const [draft, setDraft] = useState(value); useEffect(() => setDraft(value), [value, date]); return <section className="panel notes-panel"><div className="section-head"><h2>Daily notes</h2><span className="eyebrow">{formatDate(date, { month: 'short', day: 'numeric' })}</span></div><textarea value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="Capture the thought before it distracts you." /><button className="save-note" onClick={() => onSave(draft)}>Save note</button></section>; }
function ReminderPanel({ value, onSave }) { const [draft, setDraft] = useState(value); useEffect(() => setDraft(value), [value]); return <section className="panel reminder-panel"><div className="eyebrow">A gentle nudge</div><h2>What must not slip?</h2><p>{value || 'Set one reminder for later. Keep it specific and kind.'}</p><div className="reminder-input"><input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="e.g. Send the proposal at 4pm" /><button onClick={() => onSave(draft)}>Set</button></div></section>; }
function TaskModal({ task, onClose, onSave }) { const [form, setForm] = useState(task || { id: null, title: '', detail: '', time: '', endTime: '', priority: 'Medium' }); const update = (field) => (event) => setForm({ ...form, [field]: event.target.value }); return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true" aria-labelledby="task-modal-title"><button className="modal-close" onClick={onClose} aria-label="Close"><X size={17} /></button><div className="eyebrow">Habit details</div><h2 id="task-modal-title">{task ? 'Edit habit' : 'New daily habit'}</h2><label>HABIT<input autoFocus required value={form.title} onChange={update('title')} placeholder="What do you want to repeat?" /></label><label>WHY IT MATTERS<input value={form.detail} onChange={update('detail')} placeholder="A small reason to keep showing up" /></label><div className="form-row"><label>START<input type="time" value={form.time || form.startTime} onChange={update('time')} /></label><label>END<input type="time" value={form.endTime} onChange={update('endTime')} /></label></div><div className="form-row"><label>ENERGY<select value={form.priority} onChange={update('priority')}><option>High</option><option>Medium</option><option>Low</option></select></label></div><div className="modal-actions"><button className="cancel" onClick={onClose}>Cancel</button><button className="submit" disabled={!form.title.trim()} onClick={() => onSave({ ...form, id: form.id || Date.now(), title: form.title.trim(), detail: form.detail.trim() || 'A habit worth returning to', time: form.time.trim() || form.startTime || 'Anytime', endTime: form.endTime.trim() })}>Save habit</button></div></div></div>; }
function AuthModal({ onClose, onSubmit, configured }) { const [mode, setMode] = useState('signin'); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true" aria-labelledby="auth-modal-title"><button className="modal-close" onClick={onClose} aria-label="Close"><X size={17} /></button><div className="eyebrow">{configured ? 'Cloud sync' : 'Supabase setup'}</div><h2 id="auth-modal-title">{configured ? (mode === 'signin' ? 'Welcome back.' : 'Create your account.') : 'Connect Supabase first.'}</h2>{configured ? <><p className="modal-intro">Your tasks, notes, and reminders will follow you across devices.</p><label>EMAIL<input type="email" autoFocus value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@example.com" /></label><label>PASSWORD<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="At least 6 characters" /></label><div className="modal-actions"><button className="cancel" onClick={() => setMode(mode === 'signin' ? 'signup' : 'signin')}>{mode === 'signin' ? 'Create account' : 'Sign in instead'}</button><button className="submit" disabled={!email || !password} onClick={() => onSubmit(email, password, mode)}>{mode === 'signin' ? 'Sign in' : 'Sign up'}</button></div></> : <><p className="modal-intro">Copy your Supabase project URL and anonymous key into a local <strong>.env</strong> file using the provided <strong>.env.example</strong>, then restart Vite.</p><div className="modal-actions"><button className="submit" onClick={onClose}>Got it</button></div></>}</div></div>; }
function AuthLanding({ configured, onSubmit, onContinue, error }) { const [mode, setMode] = useState('signin'); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); return <div className="auth-page"><div className="auth-showcase"><div className="brand auth-brand"><span className="brand-mark"><Leaf size={17} /></span>daymark</div><div className="auth-message"><span className="eyebrow">A calmer way to work</span><h1>Make room for the work that matters.</h1><p>Put the next task first, protect a focus session, and let the rest of your day stay visible without taking over.</p><div className="auth-preview"><span className="preview-dot" /><div><strong>Next up</strong><span>Finish the project proposal</span></div><b>25:00</b></div></div><span className="auth-footnote">Your private daily workspace.</span></div><div className="auth-panel"><div className="auth-panel-inner"><div className="auth-panel-kicker">{configured ? 'Secure workspace' : 'Preview workspace'}</div><h2>{mode === 'signin' ? 'Welcome back.' : 'Start your workspace.'}</h2><p className="auth-subtitle">{configured ? 'Sign in to keep your tasks and sessions in sync everywhere.' : 'Try the task planner locally now, or connect Supabase when you are ready.'}</p>{configured ? <form onSubmit={(event) => { event.preventDefault(); onSubmit(email, password, mode); }}><label>EMAIL<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} autoFocus required placeholder="you@example.com" /></label><label>PASSWORD<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} required placeholder="Your password" /></label>{error && <div className="auth-error" role="alert">{error}</div>}<button className="auth-submit">{mode === 'signin' ? 'Sign in' : 'Create account'} <ArrowRight size={16} /></button><button type="button" className="auth-switch" onClick={() => { setMode(mode === 'signin' ? 'signup' : 'signin'); }}>{mode === 'signin' ? 'New here? Create an account' : 'Already have an account? Sign in'}</button><button type="button" className="auth-local-link" onClick={onContinue}>Continue without an account</button></form> : <><button className="auth-submit" onClick={onContinue}>Continue locally <ArrowRight size={16} /></button><button className="auth-switch" onClick={() => setMode(mode === 'signin' ? 'signup' : 'signin')}>Supabase sign-in will appear after setup</button></>}</div><div className="auth-panel-bottom"><span><Check size={14} /> Tasks first</span><span><Check size={14} /> Daily sessions</span><span><Check size={14} /> Calendar context</span></div></div></div>; }
function InsightsView({ state }) { return <MonthlyView state={state} />; }

function MonthlyView({ state }) {
  const [monthDate, setMonthDate] = useState(startOfDay(new Date()));
  const habits = state.habits || [];
  const logs = state.habitLogs || {};
  const year = monthDate.getFullYear();
  const month = monthDate.getMonth();
  const totalDays = new Date(year, month + 1, 0).getDate();
  const firstDay = new Date(year, month, 1).getDay();
  const monthKeys = Array.from({ length: totalDays }, (_, index) => keyFor(new Date(year, month, index + 1)));
  const activeDays = monthKeys.filter((day) => (logs[day] || []).length > 0).length;
  const completions = monthKeys.reduce((total, day) => total + (logs[day] || []).length, 0);
  const possible = Math.max(totalDays * habits.length, 1);
  const consistency = Math.round((completions / possible) * 100);
  const cells = [...Array(firstDay).fill(null), ...monthKeys];
  while (cells.length % 7) cells.push(null);
  return <div className="insights-page monthly-page"><div className="insight-heading"><div><div className="eyebrow">A calmer calendar</div><h2>See your month at a glance.</h2><p>Track the days you returned to your habits, then use the pattern to plan the next one.</p></div><div className="insight-period"><CalendarDays size={16} />Monthly rhythm</div></div><div className="insight-stats"><InsightStat label="Consistency" value={`${consistency}%`} note={`${completions} habit check-ins`} accent="green" /><InsightStat label="Active days" value={activeDays} note={`of ${totalDays} days this month`} accent="coral" /><InsightStat label="Daily habits" value={habits.length} note="Tracked in your routine" accent="gold" /></div><div className="month-layout"><section className="panel month-calendar"><div className="calendar-head"><strong>{formatDate(monthDate, { month: 'long', year: 'numeric' })}</strong><div><button className="mini-btn" onClick={() => setMonthDate(new Date(year, month - 1, 1))} aria-label="Previous month"><ChevronLeft size={16} /></button><button className="mini-btn" onClick={() => setMonthDate(new Date(year, month + 1, 1))} aria-label="Next month"><ChevronRight size={16} /></button></div></div><div className="month-week">{['SU', 'MO', 'TU', 'WE', 'TH', 'FR', 'SA'].map((day) => <span key={day}>{day}</span>)}</div><div className="month-days">{cells.map((day, index) => { const count = day ? (logs[day] || []).length : 0; return <div key={index} className={`month-day ${day ? '' : 'empty'} ${count === habits.length && habits.length ? 'complete' : ''}`}><span>{day ? Number(day.slice(-2)) : ''}</span>{day && <i style={{ width: `${Math.min(count / Math.max(habits.length, 1) * 100, 100)}%` }} />}</div>; })}</div><div className="month-legend"><span><i className="legend-low" />No check-ins</span><span><i className="legend-high" />All habits done</span></div></section><section className="panel month-insight"><div className="eyebrow">This month</div><h3>{activeDays ? 'Your rhythm is visible.' : 'Your month is ready to begin.'}</h3><p>{activeDays ? `You showed up on ${activeDays} ${activeDays === 1 ? 'day' : 'days'}. Keep the window realistic and let consistency build quietly.` : 'Choose one habit and give it a small, repeatable window. The first check-in creates the pattern.'}</p><div className="month-habit-list">{habits.slice(0, 4).map((habit) => { const count = monthKeys.filter((day) => (logs[day] || []).includes(habit.id)).length; return <div key={habit.id}><span>{habit.title}</span><b>{count}/{totalDays}</b></div>; })}</div></section></div></div>;
}

function WeeklyInsightsView({ state }) {
  const tasks = state.tasks;
  const completed = tasks.filter((task) => task.done).length;
  const total = tasks.length || 1;
  const completion = Math.round((completed / total) * 100);
  const priorities = ['High', 'Medium', 'Low'].map((priority) => ({ priority, count: tasks.filter((task) => task.priority === priority).length }));
  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const activity = days.map((day, index) => ({ day, value: tasks.filter((task) => task.done && (task.id + index) % 3 !== 0).length }));
  const maxActivity = Math.max(...activity.map((item) => item.value), 1);
  return <div className="insights-page"><div className="insight-heading"><div><div className="eyebrow">A clear look back</div><h2>Your attention, in patterns.</h2><p>Use these signals to decide what to protect, simplify, or move forward next.</p></div><div className="insight-period"><BarChart3 size={16} />This week</div></div><div className="insight-stats"><InsightStat label="Completion rate" value={`${completion}%`} note={`${completed} of ${tasks.length} tasks`} accent="green" /><InsightStat label="Open tasks" value={tasks.length - completed} note="Across your workspace" accent="coral" /><InsightStat label="High priority" value={priorities[0].count} note="Needs your attention" accent="gold" /></div><div className="insight-grid"><section className="chart-card panel"><div className="chart-title"><div><h3>Task activity</h3><p>Completed work across the week</p></div><span className="chart-legend"><i />Completed</span></div><div className="bar-chart">{activity.map((item) => <div className="bar-column" key={item.day}><div className="bar-track"><i style={{ height: `${Math.max(item.value / maxActivity * 100, item.value ? 22 : 4)}%` }} /></div><span>{item.day}</span></div>)}</div></section><section className="chart-card panel"><div className="chart-title"><div><h3>Priority mix</h3><p>Where your open work sits</p></div><LayoutGrid size={17} color="var(--muted)" /></div><div className="priority-chart">{priorities.map((item) => <div className="priority-line" key={item.priority}><div><span className={`priority-dot ${item.priority.toLowerCase()}`} />{item.priority}<b>{item.count}</b></div><span className="priority-progress"><i className={item.priority.toLowerCase()} style={{ width: `${Math.max(item.count / total * 100, item.count ? 10 : 0)}%` }} /></span></div>)}</div></section></div><section className="insight-callout"><Sparkles size={19} /><div><strong>Keep your next move small.</strong><span>Completion is strongest when your list has one obvious first task. Start there, then let momentum do the rest.</span></div></section></div>;
}

function InsightStat({ label, value, note, accent }) { return <div className={`insight-stat ${accent}`}><span>{label}</span><strong>{value}</strong><small>{note}</small></div>; }

function SettingsView({ state, setState, user, onSignOut }) {
  const preferences = state.preferences || { name: 'Alex', weekStarts: 'Monday', focusLength: 25, notifications: true, sound: false, compact: false, reduceMotion: false };
  const update = (key, value) => setState((current) => ({ ...current, preferences: { ...(current.preferences || preferences), [key]: value } }));
  return <div className="settings-page"><div className="settings-heading"><div><div className="eyebrow">Your workspace</div><h2>Settings</h2><p>Shape the planner around how you actually work.</p></div><div className="settings-status"><ShieldCheck size={16} />Preferences saved locally</div></div><div className="settings-layout"><section className="settings-card panel"><SettingsSection icon={<UserRound size={17} />} title="Basic settings" description="The everyday details of your planner."><div className="settings-row"><div><strong>Display name</strong><span>Used in your daily greeting</span></div><input className="settings-input" value={preferences.name} onChange={(event) => update('name', event.target.value)} /></div><div className="settings-row"><div><strong>Week starts on</strong><span>Choose the first day in your calendar</span></div><select className="settings-input" value={preferences.weekStarts} onChange={(event) => update('weekStarts', event.target.value)}><option>Monday</option><option>Sunday</option></select></div><div className="settings-row"><div><strong>Default focus length</strong><span>Used when a new session starts</span></div><select className="settings-input" value={preferences.focusLength} onChange={(event) => update('focusLength', Number(event.target.value))}><option value="15">15 minutes</option><option value="25">25 minutes</option><option value="50">50 minutes</option></select></div></SettingsSection><SettingsSection icon={<Bell size={17} />} title="Notifications" description="Keep prompts helpful, never noisy."><ToggleRow label="Daily planning reminder" detail="A gentle prompt to choose your first task" enabled={preferences.notifications} onChange={(value) => update('notifications', value)} /><ToggleRow label="Session sounds" detail="Play a small sound when focus time ends" enabled={preferences.sound} onChange={(value) => update('sound', value)} /></SettingsSection></section><section className="settings-card panel"><SettingsSection icon={<Settings2 size={17} />} title="Advanced settings" description="Fine-tune the way Daymark behaves."><ToggleRow label="Compact task rows" detail="Fit more work on the screen at once" enabled={preferences.compact} onChange={(value) => update('compact', value)} /><ToggleRow label="Reduce motion" detail="Use fewer transitions and animated effects" enabled={preferences.reduceMotion} onChange={(value) => update('reduceMotion', value)} /><div className="settings-row danger-row"><div><strong>Reset local planner</strong><span>Remove tasks, notes, and saved preferences from this browser</span></div><button className="outline-danger" onClick={() => { localStorage.removeItem(STORAGE_KEY); window.location.reload(); }}><RotateCcw size={14} />Reset</button></div></SettingsSection><SettingsSection icon={<Database size={17} />} title="Account & data" description="Your account connection and storage status."><div className="account-summary"><span className="account-avatar">{user?.email?.[0]?.toUpperCase() || 'L'}</span><div><strong>{user?.email || 'Local workspace'}</strong><span>{user ? 'Supabase sync is active' : 'Stored in this browser only'}</span></div>{user && <button className="text-btn" onClick={onSignOut}>Sign out</button>}</div></SettingsSection></section></div></div>;
}

function SettingsSection({ icon, title, description, children }) { return <div className="settings-section"><div className="settings-section-title"><span>{icon}</span><div><h3>{title}</h3><p>{description}</p></div></div>{children}</div>; }
function ToggleRow({ label, detail, enabled, onChange }) { return <div className="settings-row"><div><strong>{label}</strong><span>{detail}</span></div><button className={`switch ${enabled ? 'on' : ''}`} onClick={() => onChange(!enabled)} aria-pressed={enabled} aria-label={`${label}: ${enabled ? 'on' : 'off'}`}><i /></button></div>; }
